<?php require_once __DIR__.'/../_bootstrap.php';$u=user();if(empty($_FILES['images']))fail('Select image files');$pid=(int)($_POST['product_id']??0);$s=db()->prepare('SELECT user_id FROM products WHERE id=?');$s->execute([$pid]);if(($s->fetch()['user_id']??0)!=$u['id'])fail('Not your product',403);$dir=__DIR__.'/../../uploads/';if(!is_dir($dir))mkdir($dir,0755,true);$files=$_FILES['images'];$paths=[];foreach((array)$files['name'] as $i=>$name){if($files['error'][$i]!==UPLOAD_ERR_OK)continue;if($files['size'][$i]>5*1024*1024||!str_starts_with($files['type'][$i],'image/'))continue;$ext=pathinfo($name,PATHINFO_EXTENSION);$fn=uniqid('product_',true).'.'.$ext;move_uploaded_file($files['tmp_name'][$i],$dir.$fn);db()->prepare('INSERT INTO product_images(product_id,image_path,is_primary) VALUES(?,?,?)')->execute([$pid,'uploads/'.$fn,$i===0]);$paths[]='uploads/'.$fn;}out(['success'=>true,'images'=>$paths]);
